/**
 * ============================================================
 *  CLM SEQUENTIAL APPROVAL — COMPLETE SOLUTION
 *  Covers: Cement, RMC, BPD (Trade)
 *
 *  How it works:
 *  1. Before Business Rule (on Insert/Update → Submitted):
 *     - Runs CLMApprovalRouter to find TARGET approver role
 *     - Builds full ordered sequence from Level-1 up to target
 *     - Stores JSON sequence in u_approver_sequence
 *     - Sets u_current_approver_order = 1
 *
 *  2. Approval Action / Flow (when an approver approves):
 *     - CLMSequentialApproval.advanceToNextApprover() is called
 *     - If more approvers remain → moves to next, sends notification
 *     - If last approver approved → sets state = 'Approved'
 *
 *  3. Rejection at any level → sets state = 'Rejected' immediately
 * ============================================================
 */

// ============================================================
//  ROLE HIERARCHIES  (source of truth — edit here if SOP changes)
// ============================================================

var CLM_ROLE_HIERARCHIES = {

    // Cement Trade — May 2023 SOP
    // Net Exposure tiers (in ₹):
    //   TSH   : ≤ 10L (SD×2 max)
    //   RHM   : 10L – 30L
    //   ZHM   : 30L – 50L
    //   NSH   : 50L – 100L
    //   NSH_CCH: 100L – 150L
    //   CMO   : 150L – 250L
    //   CMO_CFO: 250L – 500L
    //   MD    : > 500L
    'Cement_Trade': [
        { role: 'TSH',      level: 1 },
        { role: 'RHM',      level: 2 },
        { role: 'ZHM',      level: 3 },
        { role: 'NSH',      level: 4 },
        { role: 'NSH_CCH',  level: 5 },
        { role: 'CMO',      level: 6 },
        { role: 'CMO_CFO',  level: 7 },
        { role: 'MD',       level: 8 }
    ],

    // RMC Trade — SOP Annexure I (iii)
    // SD Multiple × Net Exposure matrix
        'RMC_Trade': [
        { role: 'TSM',          level: 1 },
        { role: 'RH_CH_RMC',    level: 2 },
        { role: 'ZH_RMC',       level: 3 },
        { role: 'CH_RMC',       level: 4 }, // ≤₹75L step 1
        { role: 'HEAD_RMC',     level: 5 }, // ≤₹75L step 2 (target)
        { role: 'HEAD_KEY_CCH', level: 6 },
        { role: 'BH',           level: 7 },
        { role: 'BH_CFO',       level: 8 },
        { role: 'MD',           level: 9 }
    ],

    // BPD Trade — SOP Image 2
    // SD Factor × Net Exposure matrix
    'BPD_Trade': [
        { role: 'TSH_BPD',   level: 1 },
        { role: 'ZH_BPD',    level: 2 },
        { role: 'HSBPD',     level: 3 },
        { role: 'HBPD',      level: 4 },
        { role: 'CCH_HBPD',  level: 5 },
        { role: 'BH',        level: 6 },
        { role: 'CFO',       level: 7 },
        { role: 'MD',        level: 8 }
    ],

    // Cement + BPD Hybrid Trade
    'CementBpd_Trade': [
        { role: 'TSH_BPD',   level: 1 },
        { role: 'ZH_BPD',    level: 2 },
        { role: 'RHM',       level: 3 },
        { role: 'ZHM',       level: 4 },
        { role: 'NSH_CCH',   level: 5 },
        { role: 'CMO',       level: 6 },
        { role: 'CMO_CFO',   level: 7 },
        { role: 'MD',        level: 8 }
    ]
};


// ============================================================
//  HELPER: Build sequence array from hierarchy up to targetRole
// ============================================================


