function buildApproverSequence(hierarchy, targetRole, resolver, region, zone, segment, depot, isCementBpd) {

    isCementBpd = (isCementBpd === true || isCementBpd === 'true') && segment === 'BPD';

    var router = new CLMApprovalRouter();
    var validationConfig = router.getCommercialValidationConfig(targetRole, segment, isCementBpd);
    var triggersCV = validationConfig.triggersCV;

    var targetIndex = -1;
    for (var i = 0; i < hierarchy.length; i++) {
        if (hierarchy[i].role === targetRole) { targetIndex = i; break; }
    }
    if (targetIndex === -1) targetIndex = hierarchy.length - 1;

    var sequence  = [];
    var stepOrder = 1;

    function addStep(role, stepType) {
        var userSysId = resolver.getUser(role, region, zone, segment, depot, isCementBpd);

        if (!userSysId) {
            if (isCementBpd && (role === 'RHM' || role === 'ZHM')) {
                gs.warn('CLM SeqBuild [CementBPD]: no ' + role + ' mapped for region=' + region + ' zone=' + zone + ' - step skipped');
                return;
            }
            gs.error('CLM SeqBuild: no user for role=' + role + ' region=' + region + ' zone=' + zone + ' depot=' + depot + ' segment=' + segment);
        }

        sequence.push({
            order:       stepOrder++,
            role:        role,
            user_sys_id: userSysId || '',
            status:      'pending',
            step_type:   stepType
        });
    }

    function addSalesStep(role) {
        if (isCementBpd && role === 'NSH_CCH') addStep('NSH', 'sales');
        addStep(role, 'sales');
    }

    for (var j = 0; j <= targetIndex; j++) {
        var currentRole = hierarchy[j].role;

        // Commercial Validation Injection Logic
        if (triggersCV) {
 // 1. Inject ZCH before the specific tier mapped in FRS
            if ((segment === 'Cement' && currentRole === 'ZHM') ||
                (segment === 'RMC' && currentRole === 'ZH_RMC') ||
                (segment === 'BPD' && !isCementBpd && currentRole === 'ZH_BPD') ||
                (isCementBpd && segment === 'BPD' && currentRole === 'ZHM')) {     // <--- CORRECTED
                addStep('ZCH', 'commercial_validate');
            }

            // 2. Inject HO before the specific tier mapped in FRS
            if ((segment === 'Cement' && currentRole === 'NSH') ||
                (segment === 'RMC' && currentRole === 'HEAD_KEY_CCH') ||
                (segment === 'BPD' && !isCementBpd && currentRole === 'CCH_HBPD') ||
                (isCementBpd && segment === 'BPD' && currentRole === 'NSH_CCH')) {
                addStep('HO', 'commercial_validate');
            }
        }

        addSalesStep(currentRole);
    }

    if (sequence.length === 0) {
        gs.error('CLM SeqBuild: EMPTY sequence for targetRole=' + targetRole + ' segment=' + segment);
    }
    return sequence;
}

// ============================================================
//  BEFORE BUSINESS RULE
//  Table  : x_birl3_clm_clm_new_credit_request
//  When   : Before Insert / Before Update (state changes to Submitted)
//  Runs   : Server-side script
// ============================================================

