// ============================================================
//  CLMSequentialApproval Script Include
//  (replaces previous version — full rewrite)
// ============================================================

var CLMSequentialApproval = Class.create();
CLMSequentialApproval.prototype = {

    initialize: function() {},

    // ----------------------------------------------------------
    //  getCurrentApproverUserId
    //  Returns sys_id of the user who should act RIGHT NOW
    // ----------------------------------------------------------
    getCurrentApproverUserId: function(requestSysId) {
        var seq = this._getSequence(requestSysId);
        if (!seq) return '';

        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(requestSysId)) return '';
        var currentOrder = parseInt(gr.u_current_approver_order) || 1;

        for (var i = 0; i < seq.length; i++) {
            if (seq[i].order === currentOrder) return seq[i].user_sys_id;
        }
        return '';
    },

    // ----------------------------------------------------------
    //  getCurrentApproverRole
    //  Returns role label of the current pending approver
    // ----------------------------------------------------------
    getCurrentApproverRole: function(requestSysId) {
        var seq = this._getSequence(requestSysId);
        if (!seq) return '';

        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(requestSysId)) return '';
        var currentOrder = parseInt(gr.u_current_approver_order) || 1;

        for (var i = 0; i < seq.length; i++) {
            if (seq[i].order === currentOrder) return seq[i].role;
        }
        return '';
    },

    // ----------------------------------------------------------
    //  handleApproval
    //  Call this when the CURRENT approver clicks "Approve"
    //
    //  Returns:
    //    'next'   — moved to next approver (send notification)
    //    'done'   — all approved, record set to Approved
    //    'error'  — something went wrong
    // ----------------------------------------------------------
    handleApproval: function(requestSysId, approverUserId, comments) {
        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(requestSysId)) {
            gs.error('CLMSeq.handleApproval: record not found ' + requestSysId);
            return 'error';
        }

        var seq = this._parseSequence(gr.u_approver_sequence + '');
        if (!seq) return 'error';

        var currentOrder = parseInt(gr.u_current_approver_order) || 1;

        // Guard: only the correct user may approve
        var expectedUser = '';
        for (var i = 0; i < seq.length; i++) {
            if (seq[i].order === currentOrder) { expectedUser = seq[i].user_sys_id; break; }
        }
        if (approverUserId && expectedUser && approverUserId !== expectedUser) {
            gs.warn('CLMSeq.handleApproval: wrong approver. Expected=' +
                    expectedUser + ' Got=' + approverUserId);
            // Allow in case of delegation — remove this guard if not needed
        }

        // Mark current step as approved
        for (var j = 0; j < seq.length; j++) {
            if (seq[j].order === currentOrder) {
                seq[j].status           = 'approved';
                seq[j].approved_by      = approverUserId || gs.getUserID();
                seq[j].approved_on      = new GlideDateTime().toString();
                seq[j].comments         = comments || '';
                break;
            }
        }

        var totalSteps = seq.length;
        var result;

        if (currentOrder >= totalSteps) {
            // ── All levels approved ───────────────────────────
            gr.setValue('u_approver_sequence',      JSON.stringify(seq));
            gr.setValue('u_current_approver_order', currentOrder);
            gr.setValue('state',                    'Approved');
            gr.setValue('u_approver',               '');            // clear pending approver
            gr.setWorkflow(false);
            gr.autoSysFields(false);
            gr.update();

            this._triggerFinalApprovalActions(requestSysId);
            result = 'done';

        } else {
            // ── Advance to next approver ──────────────────────
            var nextOrder = currentOrder + 1;
            var nextUser  = '';
            var nextRole  = '';

            for (var k = 0; k < seq.length; k++) {
                if (seq[k].order === nextOrder) {
                    nextUser = seq[k].user_sys_id;
                    nextRole = seq[k].role;
                    break;
                }
            }

            gr.setValue('u_approver_sequence',      JSON.stringify(seq));
            gr.setValue('u_current_approver_order', nextOrder);
            gr.setValue('u_approver',               nextUser);
            gr.setWorkflow(false);
            gr.autoSysFields(false);
            gr.update();

            this._sendApprovalNotification(requestSysId, nextUser, nextRole);
            result = 'next';

            gs.info('CLMSeq: Moved to Step ' + nextOrder + ' | Role=' + nextRole +
                    ' | User=' + nextUser + ' | Request=' + requestSysId);
        }

        return result;
    },

    // ----------------------------------------------------------
    //  handleRejection
    //  Call this when ANY approver rejects
    //  Sets state = Rejected immediately (no further routing)
    // ----------------------------------------------------------
    handleRejection: function(requestSysId, approverUserId, rejectionReason) {
        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(requestSysId)) return 'error';

        var seq = this._parseSequence(gr.u_approver_sequence + '');
        var currentOrder = parseInt(gr.u_current_approver_order) || 1;

        if (seq) {
            for (var i = 0; i < seq.length; i++) {
                if (seq[i].order === currentOrder) {
                    seq[i].status      = 'rejected';
                    seq[i].approved_by = approverUserId || gs.getUserID();
                    seq[i].approved_on = new GlideDateTime().toString();
                    seq[i].comments    = rejectionReason || '';
                }
                // Mark remaining as skipped
                if (seq[i].order > currentOrder) {
                    seq[i].status = 'skipped';
                }
            }
            gr.setValue('u_approver_sequence', JSON.stringify(seq));
        }

        gr.setValue('state',        'Rejected');
        gr.setValue('u_approver',   '');
        gr.setValue('u_rejection_reason', rejectionReason || '');
        gr.setWorkflow(false);
        gr.autoSysFields(false);
        gr.update();

        this._notifyInitiatorRejection(requestSysId, rejectionReason);

        gs.info('CLMSeq: Request REJECTED at Step ' + currentOrder +
                ' by ' + (approverUserId || gs.getUserID()) +
                ' | Request=' + requestSysId);
        return 'rejected';
    },

    // ----------------------------------------------------------
    //  handleSendBack
    //  Approver sends back to initiator with comments
    //  Resets sequence order to 1 so it restarts on re-submission
    // ----------------------------------------------------------
  // ----------------------------------------------------------
    //  handleSendBack
    //  Approver sends back to initiator with comments
    //  Resets sequence order to 1 and WIPES old approver fields
    // ----------------------------------------------------------
   handleSendBack: function(requestSysId, approverUserId, sendBackComments) {
        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(requestSysId)) return 'error';

        // 1. Reset the JSON sequence
        var seq = this._parseSequence(gr.u_approver_sequence + '');
        if (seq) {
            for (var i = 0; i < seq.length; i++) {
                seq[i].status      = 'pending';
                seq[i].approved_by = '';
                seq[i].approved_on = '';
                seq[i].comments    = '';
            }
            gr.setValue('u_approver_sequence', JSON.stringify(seq));
        }

        // 2. WIPE all approver reference fields so the Flow/BR can re-populate them on Resubmit
        var approverFields = [
            'u_approver_tsh', 'u_approver_rhm', 'u_approver_zhm', 'u_approver_zch', 'u_approver_ho',
            'u_approver_nsh', 'u_approver_nsh_cch', 'u_approver_cmo', 'u_approver_cmo_cfo', 'u_approver_md',
            'u_approver_tsm', 'u_approver_rh_ch_rmc', 'u_approver_zh_rmc', 'u_approver_head_rmc', 
            'u_approver_head_key_ch_rmc', 'u_approver_head_key_cch', 'u_approver_bh', 'u_approver_bh_cfo',
            'u_approver_tsh_bpd', 'u_approver_zh_bpd', 'u_approver_hsbpd', 'u_approver_hbpd', 
            'u_approver_cch_hbpd', 'u_approver_cfo', 'u_approver','u_approver_ch_rmc'
        ];

        for (var f = 0; f < approverFields.length; f++) {
            gr.setValue(approverFields[f], ''); 
        }

        // 3. Update record status
        gr.setValue('state', 'Returned');
        gr.setValue('u_current_approver_order', 1);
        gr.setValue('return_comments', sendBackComments || '');
        gr.comments = "Returned via Approver Dashboard\nComments: " + (sendBackComments || 'None');

        // Return to initiator
        gr.setValue('approver', gr.initiator + ''); 

        gr.setWorkflow(false);
        gr.autoSysFields(false);
        gr.update();

        this._notifyInitiatorSendBack(requestSysId, sendBackComments);

        gs.info('CLMSeq: Sent Back at Step. Fields wiped | Request=' + requestSysId);
        return 'sent_back';
    },
    // ----------------------------------------------------------
    //  getSequenceSummary
    //  Returns human-readable summary for UI display
    //  Format: [{order, role, user_name, status, approved_on}]
    // ----------------------------------------------------------
    getSequenceSummary: function(requestSysId) {
        var seq = this._getSequence(requestSysId);
        if (!seq) return [];

        var summary = [];
        for (var i = 0; i < seq.length; i++) {
            var step     = seq[i];
            var userName = '';

            if (step.user_sys_id) {
                var uGr = new GlideRecord('sys_user');
                if (uGr.get(step.user_sys_id)) {
                    userName = uGr.getDisplayValue('name');
                }
            }

            summary.push({
                order:       step.order,
                role:        step.role,
                user_sys_id: step.user_sys_id,
                user_name:   userName,
                status:      step.status,
                approved_on: step.approved_on || '',
                comments:    step.comments    || ''
            });
        }
        return summary;
    },

    // ----------------------------------------------------------
    //  isCurrentApprover
    //  Returns true if the given userId is the active approver
    // ----------------------------------------------------------
    isCurrentApprover: function(requestSysId, userId) {
        var current = this.getCurrentApproverUserId(requestSysId);
        return current !== '' && current === userId;
    },

    // ── Private helpers ─────────────────────────────────────

    _getSequence: function(requestSysId) {
        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(requestSysId)) return null;
        return this._parseSequence(gr.u_approver_sequence + '');
    },

    _parseSequence: function(json) {
        if (!json || json === '' || json === 'null') return null;
        try {
            return JSON.parse(json);
        } catch (e) {
            gs.error('CLMSeq._parseSequence: invalid JSON — ' + e.message);
            return null;
        }
    },

    // _triggerFinalApprovalActions: function(requestSysId) {
    //     // TODO: trigger SAP write-back, send approval notification to initiator
    //     // Placeholder — wire up your SAP integration here
    //     gs.info('CLMSeq: Final approval actions triggered for ' + requestSysId);

    //     // Example: fire a ServiceNow event
    //     // GlideEvent.queue('x_birl3_clm.approved', requestSysId, '', '');
    // },
//30 april 2026

_triggerFinalApprovalActions: function(requestSysId) {
    var seq = this._getSequence(requestSysId);
    if (seq && seq.length > 0) {
        var lastStep = seq[seq.length - 1];
        gs.info('CLMSeq: Final approver role=' + lastStep.role + 
                ' type=' + lastStep.step_type);
    }
    // TODO: SAP write-back integration here
    gs.info('CLMSeq: Final approval actions triggered for ' + requestSysId);
},
    _sendApprovalNotification: function(requestSysId, userSysId, role) {
        // TODO: Send email/push to next approver
        // Placeholder — wire up notification record here
        gs.info('CLMSeq: Notification → ' + userSysId + ' (' + role + ')' +
                ' for request ' + requestSysId);

        // Example using GlideEmailOutbound or notification event:
        // GlideEvent.queue('x_birl3_clm.pending_approval', requestSysId, userSysId, role);
    },

    _notifyInitiatorRejection: function(requestSysId, reason) {
        gs.info('CLMSeq: Rejection notification for request ' + requestSysId);
        // GlideEvent.queue('x_birl3_clm.rejected', requestSysId, '', reason);
    },

    _notifyInitiatorSendBack: function(requestSysId, comments) {
        gs.info('CLMSeq: SendBack notification for request ' + requestSysId);
        // GlideEvent.queue('x_birl3_clm.sent_back', requestSysId, '', comments);
    },

    type: 'CLMSequentialApproval'
};


