/*
------------------------------------------------------------------
SCENARIO 1 — Cement Trade, Net Exposure ₹40L (→ ZHM is target)
------------------------------------------------------------------
Hierarchy : TSH → RHM → ZHM → NSH → NSH_CCH → CMO → CMO_CFO → MD
Target    : ZHM (level 3)
Sequence built: [TSH, RHM, ZHM]  (3 steps)

Step 1: TSH approves → u_current_approver_order = 2, u_approver = RHM's user
Step 2: RHM approves → u_current_approver_order = 3, u_approver = ZHM's user
Step 3: ZHM approves → state = 'Approved', SAP write-back triggered

------------------------------------------------------------------
SCENARIO 2 — RMC Trade, Net Exposure ₹20L (→ ZH_RMC is target)
------------------------------------------------------------------
Hierarchy : TSM → RH_CH_RMC → ZH_RMC → HEAD_RMC → ...
Target    : ZH_RMC (level 3)
Sequence  : [TSM, RH_CH_RMC, ZH_RMC]  (3 steps)

------------------------------------------------------------------
SCENARIO 3 — BPD Trade, Net Exposure ₹60L, Deviation (→ HBPD+1 = CCH_HBPD)
------------------------------------------------------------------
Hierarchy : TSH_BPD → ZH_BPD → HSBPD → HBPD → CCH_HBPD → BH → CFO → MD
Target    : CCH_HBPD (level 5, escalated from HBPD)
Sequence  : [TSH_BPD, ZH_BPD, HSBPD, HBPD, CCH_HBPD]  (5 steps)

------------------------------------------------------------------
REJECTION MID-SEQUENCE — e.g., RHM rejects at step 2
------------------------------------------------------------------
- seq[1].status = 'rejected'
- seq[2..].status = 'skipped'
- state = 'Rejected'
- Initiator notified immediately

------------------------------------------------------------------
SEND BACK at step 3
------------------------------------------------------------------
- All seq steps reset to 'pending'
- u_current_approver_order = 1
- state = 'Sent Back'
- On re-submission, Before BR rebuilds/validates sequence & restarts from step 1
*/
